function Initialize-Directory([string]$Path) { if (-not [IO.Directory]::Exists($Path)) { [IO.Directory]::CreateDirectory($Path) | Out-Null } }
function Get-FileSha256([string]$Path) { if (-not [IO.File]::Exists($Path)) { return '' }; return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant() }
function Write-Artifact([string]$Name, [AllowEmptyString()][string]$Value) { [IO.File]::WriteAllText((Join-Path $EvidenceRoot $Name), $Value, (New-Object Text.UTF8Encoding($false))) }
function Write-JsonArtifact([string]$Name, $Value) { Write-Artifact $Name (($Value | ConvertTo-Json -Depth 40) + [Environment]::NewLine) }
function Add-Gate([string]$Name, [string]$Result, [string]$Detail) { [void]$Gates.Add([pscustomobject]@{ gate = $Name; status = $Result; detail = $Detail }) }
function Add-Failure([string]$Class, [string]$Detail) { [void]$Failures.Add([pscustomobject]@{ failureClass = $Class; detail = $Detail; status = 'ACTIVE' }); if ([string]::IsNullOrWhiteSpace($PrimaryFailure)) { $script:PrimaryFailure = $Class } }
function Set-Gate([bool]$Condition, [string]$Name, [string]$FailureClass, [string]$Detail) { if ($Condition) { Add-Gate $Name 'PASS' $Detail } else { Add-Failure $FailureClass $Detail; Add-Gate $Name 'BLOCKED' $Detail } }
function Get-GitText([string[]]$Arguments) { $stdoutPath=[IO.Path]::GetTempFileName(); $stderrPath=[IO.Path]::GetTempFileName(); try { & git.exe -C $WorkspaceRoot -c core.autocrlf=false @Arguments 1> $stdoutPath 2> $stderrPath; $exitCode=$LASTEXITCODE; $stdoutText=''; $stderrText=''; if(Test-Path $stdoutPath){$stdoutText=[IO.File]::ReadAllText($stdoutPath)}; if(Test-Path $stderrPath){$stderrText=[IO.File]::ReadAllText($stderrPath)}; return [pscustomobject]@{exitCode=$exitCode;lines=@($stdoutText -split [Environment]::NewLine | Where-Object{$_ -ne ''});stderr=$stderrText} } finally { Remove-Item $stdoutPath,$stderrPath -Force -ErrorAction SilentlyContinue } }
function Get-GitStatusRecords {
    $stdoutPath=[IO.Path]::GetTempFileName(); $stderrPath=[IO.Path]::GetTempFileName()
    try { & git.exe -C $WorkspaceRoot -c core.autocrlf=false status --porcelain=v1 -z --untracked-files=all 1> $stdoutPath 2> $stderrPath; $exitCode=$LASTEXITCODE; $raw=''; $stderr=''; if(Test-Path $stdoutPath){$raw=[IO.File]::ReadAllText($stdoutPath)}; if(Test-Path $stderrPath){$stderr=[IO.File]::ReadAllText($stderrPath)} } finally { Remove-Item $stdoutPath,$stderrPath -Force -ErrorAction SilentlyContinue }
    if ($exitCode -ne 0) { throw ('git status failed with exit ' + $exitCode) }
    $records = @()
    $parts = ([string]($raw -join '')) -split [char]0
    foreach ($part in $parts) {
        if ([string]::IsNullOrWhiteSpace($part)) { continue }
        if ($part.Length -lt 4) { continue }
        $status = $part.Substring(0,2)
        $path = $part.Substring(3)
        $records += [pscustomobject]@{ status = $status; path = $path }
    }
    return ,$records
}
function Get-Classification([string]$Path, [string]$StatusCode, [string]$DiffText) {
    $lower = $Path.ToLowerInvariant()
    $class = 'UNKNOWN_OR_CONFLICTING_OWNERSHIP'
    $basis = 'No positive ownership rule matched'
    $owner = 'unknown'
    $relevance = 'UNKNOWN'
    $generated = 'UNKNOWN'
    $phase = 'UNPROVEN'
    $include = $false
    $secret = 'NOT_SCANNED'
    if ($lower -match '(^|[\\/])\.env($|\.)|credential|secret|private[-_]?key|api[-_]?key|token') { $class = 'SECRET_OR_CREDENTIAL_MATERIAL'; $basis = 'Credential-shaped filename or environment material'; $owner = 'local-security'; $relevance = 'EXCLUDE'; $generated = 'NO'; $phase = 'LOCAL'; $secret = 'REVIEW_REQUIRED'; return [pscustomobject]@{classification=$class;classificationBasis=$basis;likelyOwner=$owner;releaseRelevance=$relevance;generatedArtifactStatus=$generated;phaseLineage=$phase;includeInReleaseSourceSet=$include;secretScanStatus=$secret;requiresUserDecision=$true;notes='Never include automatically'} }
    if ($lower -match '(^|[\\/])(\.apex-evidence|apex-reports|evidence|playwright-report|test-results|chat_logs|logs|backups)([\\/]|$)|\.zip$|\.tgz$|\.tar\.gz$|\.parser\.json$|\.final-reopen-validation\.json$') { $class = 'GENERATED_EVIDENCE_OR_REPORT'; $basis = 'Evidence/report/archive naming and location'; $owner = 'APEX-governance'; $relevance = 'EXCLUDE'; $generated = 'YES'; $phase = 'APEX'; $secret = 'SCANNED_NO_VALUE'; return [pscustomobject]@{classification=$class;classificationBasis=$basis;likelyOwner=$owner;releaseRelevance=$relevance;generatedArtifactStatus=$generated;phaseLineage=$phase;includeInReleaseSourceSet=$include;secretScanStatus=$secret;requiresUserDecision=$false;notes='Preserved outside release source set'} }
    if ($lower -match '(^|[\\/])\.?(venv|node_modules|\.pma|\.tools|\.pytest_cache|\.playwright|\.snapshots|\.deploy-staging|\.git-filter-repo-mirror|runtime|tmp|temp_patch|test-results)([\\/]|$)') { $class = 'LOCAL_RUNTIME_OR_CACHE'; $basis = 'Local runtime, cache, temporary, or dependency path'; $owner = 'local-runtime'; $relevance = 'EXCLUDE'; $generated = 'YES_OR_LOCAL'; $phase = 'LOCAL'; $secret = 'SCANNED_NO_VALUE'; return [pscustomobject]@{classification=$class;classificationBasis=$basis;likelyOwner=$owner;releaseRelevance=$relevance;generatedArtifactStatus=$generated;phaseLineage=$phase;includeInReleaseSourceSet=$include;secretScanStatus=$secret;requiresUserDecision=$false;notes='Preserved in canonical worktree'} }
    if ($lower -match '^apex_.*\.(ps1|md)$|(^|[\\/])pma[\\/]feature-gates[\\/]|(^|[\\/])\.github[\\/]skills[\\/]') { $class = 'APEX_CONTROLLER_OR_AUTHORITY'; $basis = 'APEX authority, controller, skill, or failure register'; $owner = 'APEX-governance'; $relevance = 'EXCLUDE'; $generated = 'NO'; $phase = 'APEX'; $secret = 'SCANNED_NO_VALUE'; return [pscustomobject]@{classification=$class;classificationBasis=$basis;likelyOwner=$owner;releaseRelevance=$relevance;generatedArtifactStatus=$generated;phaseLineage=$phase;includeInReleaseSourceSet=$include;secretScanStatus=$secret;requiresUserDecision=$false;notes='Governance material, not production source'} }
    $approvedPath = $lower -in @('apps/gateway-api/src/routes/admin-crm-contacts.ts','apps/web-user/src/components/superadmin/superadmincrmcommandcenter.tsx')
    if ($approvedPath -and $DiffText -match '(?i)crm|contact|canary|superadmin|erpnext') { $class = 'APPROVED_STAGE_X_RELEASE_SOURCE'; $basis = 'Path and diff contain the proven Phase 7 CRM/Superadmin lineage'; $owner = 'Stage-X CRM'; $relevance = 'INCLUDE'; $generated = 'NO'; $phase = 'PHASE7_CONSUMED'; $include = $true; $secret = 'SCANNED_NO_VALUE'; return [pscustomobject]@{classification=$class;classificationBasis=$basis;likelyOwner=$owner;releaseRelevance=$relevance;generatedArtifactStatus=$generated;phaseLineage=$phase;includeInReleaseSourceSet=$include;secretScanStatus=$secret;requiresUserDecision=$false;notes='Approved only with semantic lineage marker'} }
    if ($lower -match '^apps[\\/]|^data[\\/]|^mof[\\/]|^public[\\/]') { $class = 'PREEXISTING_UNRELATED_USER_WORK'; $basis = 'Application/content path outside proven Phase 7 CRM lineage; preserved and excluded'; $owner = 'workspace-user'; $relevance = 'EXCLUDE'; $generated = 'NO_OR_UNKNOWN'; $phase = 'OUTSIDE_PHASE8A'; $secret = 'SCANNED_NO_VALUE'; return [pscustomobject]@{classification=$class;classificationBasis=$basis;likelyOwner=$owner;releaseRelevance=$relevance;generatedArtifactStatus=$generated;phaseLineage=$phase;includeInReleaseSourceSet=$include;secretScanStatus=$secret;requiresUserDecision=$false;notes='Requires later authority if released'} }
    if ($lower -match '^scripts[\\/]|^tools[\\/]|^pma[\\/]|^tmp') { $class = 'APEX_CONTROLLER_OR_AUTHORITY'; $basis = 'Script/tooling path retained as governance or local automation material'; $owner = 'workspace-tooling'; $relevance = 'EXCLUDE'; $generated = 'NO_OR_LOCAL'; $phase = 'LOCAL'; $secret = 'SCANNED_NO_VALUE'; return [pscustomobject]@{classification=$class;classificationBasis=$basis;likelyOwner=$owner;releaseRelevance=$relevance;generatedArtifactStatus=$generated;phaseLineage=$phase;includeInReleaseSourceSet=$include;secretScanStatus=$secret;requiresUserDecision=$false;notes='Excluded from candidate'} }
    return [pscustomobject]@{classification=$class;classificationBasis=$basis;likelyOwner=$owner;releaseRelevance=$relevance;generatedArtifactStatus=$generated;phaseLineage=$phase;includeInReleaseSourceSet=$include;secretScanStatus=$secret;requiresUserDecision=$true;notes='Hard blocker until positively classified'}
}

