    $prePass = ($preHash -eq $PredecessorHashExpected -and $null -ne $preSide -and [string]$preSide.status -eq 'PASS' -and [string]$preSide.sha256 -eq $preHash -and [int]$preSide.entryCount -eq 46)
    Write-JsonArtifact '04_PHASE8_PREDECESSOR_VALIDATION.json' ([pscustomobject]@{zip=$PredecessorZip;sidecar=$PredecessorSidecar;sha256=$preHash;expectedSha256=$PredecessorHashExpected;sidecarStatus=[string]$preSide.status;sidecarSha256=[string]$preSide.sha256;entryCount=[int]$preSide.entryCount;pass=$prePass;localReleaseCandidate='BLOCKED';productionAuthorization='NO';productionMutation='NO'})
    Set-Gate $prePass 'PHASE8_PREDECESSOR_VALIDATION' 'PHASE8_PREDECESSOR_VALIDATION_FAILED' 'Phase 8 blocked package independently reopened and matched'

    $headResult = Get-GitText @('rev-parse','HEAD'); $branchResult = Get-GitText @('branch','--show-current'); $upstreamResult = Get-GitText @('rev-parse','--abbrev-ref','--symbolic-full-name','@{u}'); $upstreamShaResult = Get-GitText @('rev-parse','@{u}')
    $records = Get-GitStatusRecords; $statusLines = @($records | ForEach-Object { $_.status + ' ' + $_.path }); $diffResult = Get-GitText @('diff','--name-status'); $cachedResult = Get-GitText @('diff','--cached','--name-status'); $othersResult = Get-GitText @('ls-files','--others','--exclude-standard'); $stashesResult = Get-GitText @('stash','list'); $remotesResult = Get-GitText @('remote','-v'); $diffLines = @($diffResult.lines); $cachedLines = @($cachedResult.lines); $others = @($othersResult.lines); $stashes = @($stashesResult.lines); $remotes = @($remotesResult.lines)
    Write-JsonArtifact '05_GIT_ENTRY_BASELINE.json' ([pscustomobject]@{utc=(Get-Date).ToUniversalTime().ToString('o');root=$WorkspaceRoot;currentDirectory=(Get-Location).Path;branch=[string]$branchResult.lines[0];head=[string]$headResult.lines[0];upstream=[string]$upstreamResult.lines[0];upstreamSha=[string]$upstreamShaResult.lines[0];dirtyPathCount=$records.Count;status=$statusLines;diffNameStatus=$diffLines;cachedNameStatus=$cachedLines;untracked=$others;stashes=$stashes;remotes=$remotes;destructiveGitCleanup='NO'})

    $inventory = @(); foreach ($record in $records) { $full = Join-Path $WorkspaceRoot $record.path; $item = Get-Item -LiteralPath $full -Force -ErrorAction SilentlyContinue; $size=0; $kind='missing'; $mtime=''; $sha=''; if ($null -ne $item) { $mtime=$item.LastWriteTimeUtc.ToString('o'); if ($item.PSIsContainer) { $kind='directory' } else { $kind='file'; $size=$item.Length; $sha=Get-FileSha256 $full } }; $diffText=''; if ($record.status -notmatch '\?') { $recordDiff=Get-GitText @('diff','--',$record.path); $diffText = [string](@($recordDiff.lines) -join [Environment]::NewLine) }; $classification=Get-Classification $record.path $record.status $diffText; $headBlob=''; if ($record.status -notmatch '\?') { $blobResult=Get-GitText @('rev-parse','HEAD:' + $record.path); $headBlob=[string](@($blobResult.lines) -join '') }; $inventory += [pscustomobject]@{path=$record.path;gitStatus=$record.status;tracked=($record.status -notmatch '\?');untracked=($record.status -match '\?');staged=($record.status.Substring(0,1) -ne ' ');exists=($null -ne $item);fileOrDirectory=$kind;sizeBytes=$size;sha256=$sha;lastWriteTimeUtc=$mtime;gitBlobAtHead=$headBlob;headBlobSha=$headBlob;workingTreeSha=$sha;diffSummary=if($diffText.Length -gt 400){$diffText.Substring(0,400)}else{$diffText};firstSeenEvidence='Phase8A current entry freeze';likelyOwner=$classification.likelyOwner;releaseRelevance=$classification.releaseRelevance;classification=$classification.classification;classificationBasis=$classification.classificationBasis;secretScanStatus=$classification.secretScanStatus;generatedArtifactStatus=$classification.generatedArtifactStatus;phaseLineage=$classification.phaseLineage;includeInReleaseSourceSet=$classification.includeInReleaseSourceSet;requiresUserDecision=$classification.requiresUserDecision;notes=$classification.notes} }
    Write-JsonArtifact '07_DIRTY_PATH_INVENTORY.json' $inventory
