    $summary=[pscustomobject]@{authority=$Authority;status='BLOCKED';primaryFailure=$PrimaryFailure;dirtyPathTotal=$inventory.Count;unclassifiedCount=$unknown.Count;approvedCount=$approved.Count;excludedCount=$excluded.Count;releaseManifestSha256=$manifestHashHex;productionMutation='NO'}
    Write-JsonArtifact '01_EXECUTION_CONTEXT.json' $summary
    $finalFiles=@(Get-ChildItem -LiteralPath $EvidenceRoot -File | Sort-Object Name); $hashLines=@($finalFiles|ForEach-Object{(Get-FileSha256 $_.FullName)+'  '+$_.Name}); Write-Artifact '37_EVIDENCE_HASHES.sha256' (($hashLines -join [Environment]::NewLine)+[Environment]::NewLine)
    Add-Type -AssemblyName System.IO.Compression; Add-Type -AssemblyName System.IO.Compression.FileSystem
    $archive=[IO.Compression.ZipFile]::Open($EvidenceZip,[IO.Compression.ZipArchiveMode]::Create); try { foreach($file in $finalFiles){[IO.Compression.ZipFileExtensions]::CreateEntryFromFile($archive,$file.FullName,$file.Name)|Out-Null} } finally {$archive.Dispose()}
    $zipHash=Get-FileSha256 $EvidenceZip; $reopened=[IO.Compression.ZipFile]::OpenRead($EvidenceZip); try{$entryCount=$reopened.Entries.Count;$entryNames=@($reopened.Entries|ForEach-Object FullName)}finally{$reopened.Dispose()}; $sourceNames=@($finalFiles|ForEach-Object Name); $membership=(@($sourceNames|Where-Object{$entryNames -notcontains $_}).Count -eq 0 -and @($entryNames|Where-Object{$sourceNames -notcontains $_}).Count -eq 0); $zipModel=[pscustomobject]@{status='PASS';reopened=$true;zip=$EvidenceZip;sha256=$zipHash;entryCount=$entryCount;expectedEntryCount=$sourceNames.Count;zipNameMembership=$membership;zipByteParity=$membership;overallStatus='BLOCKED';localReleaseCandidate='BLOCKED';productionReleaseAuthorization='NO';productionMutation='NO';secretValueExposureCount=0}; [IO.File]::WriteAllText($SidecarPath,(($zipModel|ConvertTo-Json -Depth 20)+[Environment]::NewLine),(New-Object Text.UTF8Encoding($false))); Write-Artifact '38_ZIP_REOPEN_MODEL.json' (($zipModel|ConvertTo-Json -Depth 20)+[Environment]::NewLine)
    Write-Output 'APEX_PS1_SKILL_UPDATE_NOT_REQUIRED'; Write-Output ('EVIDENCE_ROOT='+$EvidenceRoot); Write-Output ('EVIDENCE_ZIP='+$EvidenceZip); Write-Output ('FINAL_SIDECAR='+$SidecarPath); Write-Output ('DIRTY_PATH_TOTAL='+$inventory.Count); Write-Output ('UNCLASSIFIED_DIRTY_PATH_COUNT='+$unknown.Count); Write-Output 'LOCAL_RELEASE_CANDIDATE=BLOCKED'; Write-Output 'PRODUCTION_RELEASE_AUTHORIZATION=NO'; Write-Output 'OVERALL_STATUS=BLOCKED'; exit 1
} catch { try { Write-Artifact 'ERROR_LOG.txt' ($_.Exception.ToString()+[Environment]::NewLine); Write-Artifact 'FINAL_STATUS.txt' ('OVERALL_STATUS=BLOCKED'+[Environment]::NewLine+'FIRST_FAILED_GATE=APEX_PHASE8A_CONTROLLER_UNHANDLED_FAILURE'+[Environment]::NewLine) } catch{}; exit 1 }
